/**
 * @planks("the TodoMVC app is loaded")
 * @planks("the todo list is empty")
 * @planks("I type {string} into the new-todo input and press Enter")
 * @planks("the todo {string} appears in the list")
 * @planks("the new-todo input is cleared")
 * @planks("the todo list remains empty")
 * @planks("I click the toggle checkbox for {string}")
 * @planks("the todo {string} has the class {string}")
 * @planks("the todo {string} does not have the class {string}")
 * @planks("I click the {string} toggle")
 * @planks("all todos have the class {string}")
 * @planks("I complete all todos individually")
 * @planks("the {string} checkbox is checked")
 * @planks("I click the \"Clear completed\" button")
 * @planks("the todo list contains only {string}")
 * @planks("the \"Clear completed\" button is not visible")
 * @planks("I click the destroy button for {string}")
 * @planks("the main section is hidden")
 * @planks("the footer section is hidden")
 * @planks("the main section is visible")
 * @planks("the footer section is visible")
 * @planks("the todo-count shows {string}")
 * @planks("I double-click the label for {string}")
 * @planks("the todo has the class {string}")
 * @planks("the edit input contains {string}")
 * @planks("I change the edit input to {string} and press Enter")
 * @planks("I change the edit input to {string} and tab away")
 * @planks("I change the edit input to {string} and press Escape")
 * @planks("I clear the edit input and press Enter")
 * @planks("the todo does not have the class {string}")
 * @planks("the URL hash is {string}")
 * @planks("the todo list shows {string} and {string}")
 * @planks("the todo list shows only {string}")
 * @planks("I navigate to the {string} route")
 * @planks("the {string} filter link has the class {string}")
 * @planks("the {string} filter link does not have the class {string}")
 * @planks("I click the {string} filter link")
 * @planks("I am viewing the active filter")
 * @planks("I am viewing the completed filter")
 * @planks("I complete the todo {string}")
 * @planks("the localStorage key {string} contains an item with title {string}")
 * @planks("localStorage has the following todos")
 * @planks("I reload the app")
 * @planks("the localStorage item for {string} has completed set to true")
 * @planks("the localStorage key {string} has no items")
 * @planks("Persist todos to localStorage")
 * @planks("Restore todos from localStorage on load")
 * @planks("Persist completed state to localStorage")
 * @planks("Persist deleted todos — removed from localStorage")
 * @planks("Persist filter state across reload")
 * @planks("Do not persist editing state")
 * @planks("all todos are completed")
 * @planks("the first todo is completed")
 * @planks("I have stored references to the todo list items")
 * @planks("all previously stored todo references are still attached to the DOM")
 */
(function () {
  var STORAGE_KEY = 'todos-javascript';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';
  var editingId = null;

  var newTodo = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAll = document.getElementById('toggle-all');
  var clearCompleted = document.querySelector('.clear-completed');
  var todoCount = document.querySelector('.todo-count');
  var filters = document.querySelectorAll('.filters a');

  function loadTodos() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      if (data) { todos = JSON.parse(data); }
    } catch (e) { todos = []; }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getFilter() {
    var hash = location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function filteredTodos() {
    var f = getFilter();
    if (f === 'active') return todos.filter(function (t) { return !t.completed; });
    if (f === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function activeCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function completedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  /**
   * @planks("I clear the edit input and press Enter")
   * Stale-removal loop (line ~210) calls removeChild which can trigger reentrant render
   * via the capture-phase blur event handler. Underlying cause of NotFoundError in real
   * browser when editing a todo to empty text with 2+ items present.
   */
  function render() {
    var items = todos;
    var f = getFilter();
    // Build map of existing li elements by data-id
    var existing = {};
    var child = todoList.firstElementChild;
    while (child) {
      var id = Number(child.getAttribute('data-id'));
      existing[id] = child;
      child = child.nextElementSibling;
    }
    var idsSeen = {};
    var fragment = document.createDocumentFragment();
    for (var i = 0; i < items.length; i++) {
      var t = items[i];
      idsSeen[t.id] = true;
      var li;
      if (existing[t.id]) {
        // Reuse existing li element to preserve DOM references
        li = existing[t.id];
        delete existing[t.id];
        // Update class, style, and inner content
        var liClass = '';
        if (t.completed) {
          if (liClass) liClass += ' ';
          liClass += 'completed';
        }
        if (t.id === editingId) {
          if (liClass) liClass += ' ';
          liClass += 'editing';
        }
        li.className = liClass;
        var hidden = (f === 'active' && t.completed) || (f === 'completed' && !t.completed);
        if (hidden) {
          li.setAttribute('style', 'display:none');
        } else {
          li.removeAttribute('style');
        }
        // Update inner content
        var viewDiv = li.querySelector('.view');
        if (!viewDiv) {
          viewDiv = document.createElement('div');
          viewDiv.className = 'view';
          li.appendChild(viewDiv);
        }
        var toggle = viewDiv.querySelector('.toggle');
        if (!toggle) {
          toggle = document.createElement('input');
          toggle.className = 'toggle';
          toggle.type = 'checkbox';
          viewDiv.insertBefore(toggle, viewDiv.firstChild);
        }
        toggle.checked = t.completed;
        var label = viewDiv.querySelector('label');
        if (!label) {
          label = document.createElement('label');
          viewDiv.appendChild(label);
        }
        label.textContent = t.title;
        var destroy = viewDiv.querySelector('.destroy');
        if (!destroy) {
          destroy = document.createElement('button');
          destroy.className = 'destroy';
          viewDiv.appendChild(destroy);
        }
        var editInput = li.querySelector('.edit');
        if (!editInput) {
          editInput = document.createElement('input');
          editInput.className = 'edit';
          li.appendChild(editInput);
        }
        editInput.value = t.title;
      } else {
        // Create new li element
        var liClass = '';
        var hidden = false;
        if (t.completed) {
          if (liClass) liClass += ' ';
          liClass += 'completed';
        }
        if (t.id === editingId) {
          if (liClass) liClass += ' ';
          liClass += 'editing';
        }
        if (f === 'active' && t.completed) hidden = true;
        if (f === 'completed' && !t.completed) hidden = true;
        var html = '<li class="' + liClass + '" data-id="' + t.id + '"' + (hidden ? ' style="display:none"' : '') + '>';
        html += '<div class="view">';
        html += '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>';
        html += '<label>' + escapeHtml(t.title) + '</label>';
        html += '<button class="destroy"></button>';
        html += '</div>';
        html += '<input class="edit" value="' + escapeHtml(t.title) + '">';
        html += '</li>';
        var temp = document.createElement('div');
        temp.innerHTML = html;
        li = temp.firstElementChild;
      }
      fragment.appendChild(li);
    }
    // Remove stale li elements that no longer have a matching todo
    for (var staleId in existing) {
      var stale = existing[staleId];
      if (stale.parentNode) stale.parentNode.removeChild(stale);
    }
    // Replace children in one operation
    todoList.innerHTML = '';
    todoList.appendChild(fragment);

    var count = activeCount();
    var word = count === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + count + '</strong> ' + word + ' left';

    if (todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = 'block';
      footer.style.display = 'block';
    }

    toggleAll.checked = todos.length > 0 && completedCount() === todos.length;

    if (completedCount() === 0) {
      clearCompleted.style.display = 'none';
    } else {
      clearCompleted.style.display = 'block';
    }

    var currentFilter = getFilter();
    for (var j = 0; j < filters.length; j++) {
      var a = filters[j];
      var href = a.getAttribute('href');
      if ((href === '#/' && currentFilter === 'all') ||
          (href === '#/active' && currentFilter === 'active') ||
          (href === '#/completed' && currentFilter === 'completed')) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  function escapeHtml(str) {
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    var id = Date.now() + Math.random();
    todos.push({ id: id, title: trimmed, completed: false });
    saveTodos();
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function toggleAllTodos() {
    var allCompleted = todos.length > 0 && completedCount() === todos.length;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = !allCompleted;
    }
    saveTodos();
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  /**
   * @planks("I clear the edit input and press Enter")
   * Empty-trimmed-title path calls removeTodo which calls render(). When called from
   * the blur handler during render()'s stale-removal loop, this causes reentrant render
   * and a stale removeChild.
   */
  function updateTodo(id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      removeTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    saveTodos();
    editingId = null;
    render();
  }

  function cancelEdit() {
    editingId = null;
    render();
  }

  // --- Event delegation ---

  toggleAll.addEventListener('click', function () {
    toggleAllTodos();
  });

  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  todoList.addEventListener('click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = Number(li.getAttribute('data-id'));
    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (e.target.classList.contains('destroy')) {
      removeTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    var id = Number(li.getAttribute('data-id'));
    editingId = id;
    render();
    var editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.focus();
      editInput.setSelectionRange(editInput.value.length, editInput.value.length);
    }
  });

  todoList.addEventListener('keydown', function (e) {
    var li = e.target.closest('li.editing');
    if (!li) return;
    var id = Number(li.getAttribute('data-id'));
    var editInput = li.querySelector('.edit');
    if (e.keyCode === ENTER_KEY) {
      updateTodo(id, editInput.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      cancelEdit();
    }
  });

  /**
   * @planks("I clear the edit input and press Enter")
   * Capture-phase blur listener. When the editing LI is removed from the DOM during
   * render()'s stale-removal loop, the blur event fires synchronously and calls
   * updateTodo(), which re-enters render() — the root cause of the NotFoundError crash.
   */
  todoList.addEventListener('blur', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li.editing');
    if (!li) return;
    var id = Number(li.getAttribute('data-id'));
    updateTodo(id, editInput.value);
  }, true);

  window.addEventListener('hashchange', function () {
    editingId = null;
    loadTodos();
    render();
  });

  // --- Init ---
  loadTodos();
  render();
})();

